459:     @GuardedBy("availableMemorySegments")
460:     private boolean requestMemorySegmentFromGlobal() {
461:         assert Thread.holdsLock(availableMemorySegments);
462: 
463:         if (isRequestedSizeReached()) {
464:             return false;
465:         }
466: 
467:         MemorySegment segment = requestPooledMemorySegment();
468:         if (segment != null) {
469:             availableMemorySegments.add(segment);
470:             return true;
471:         }
472:         return false;
473:     }
474: 
475:     @GuardedBy("availableMemorySegments")
476:     private MemorySegment requestOverdraftMemorySegmentFromGlobal() {
477:         assert Thread.holdsLock(availableMemorySegments);
478: 
479:         // if overdraft buffers(i.e. buffers exceeding poolSize) is greater than or equal to
480:         // maxOverdraftBuffersPerGate, no new buffer can be requested.
481:         if (numberOfRequestedMemorySegments - currentPoolSize >= maxOverdraftBuffersPerGate) {
482:             return null;
483:         }
484: 
485:         return requestPooledMemorySegment();
486:     }
487: 
488:     @Nullable
489:     @GuardedBy("availableMemorySegments")
490:     private MemorySegment requestPooledMemorySegment() {
491:         checkState(
492:                 !isDestroyed,
493:                 "Destroyed buffer pools should never acquire segments - this will lead to buffer leaks.");
494: 
495:         MemorySegment segment = networkBufferPool.requestPooledMemorySegment();
496:         if (segment != null) {
497:             numberOfRequestedMemorySegments++;
498:         }
499:         return segment;
500:     }
501: 
502:     /**
503:      * Tries to obtain a buffer from global pool as soon as one pool is available. Note that
504:      * multiple {@link LocalBufferPool}s might wait on the future of the global pool, hence this
505:      * method double-check if a new buffer is really needed at the time it becomes available.
506:      */
507:     @GuardedBy("availableMemorySegments")
508:     private void requestMemorySegmentFromGlobalWhenAvailable() {
509:         assert Thread.holdsLock(availableMemorySegments);
510: 
511:         checkState(
512:                 !requestingNotificationOfGlobalPoolAvailable,
513:                 "local buffer pool is already in the state of requesting memory segment from global when it is available.");
514:         requestingNotificationOfGlobalPoolAvailable = true;
515:         assertNoException(
516:                 networkBufferPool.getAvailableFuture().thenRun(this::onGlobalPoolAvailable));
517:     }
518: 
519:     private void onGlobalPoolAvailable() {
520:         CompletableFuture<?> toNotify;
521:         synchronized (availableMemorySegments) {
522:             requestingNotificationOfGlobalPoolAvailable = false;
523:             if (isDestroyed || availabilityHelper.isApproximatelyAvailable()) {
524:                 // there is currently no benefit to obtain buffer from global; give other pools
525:                 // precedent
526:                 return;
527:             }
528: 
529:             // Check availability and potentially request the memory segment. The call may also
530:             // result in invoking
531:             // #requestMemorySegmentFromGlobalWhenAvailable again if no segment could be fetched
532:             // because of
533:             // concurrent requests from different LocalBufferPools.
534:             toNotify = checkAndUpdateAvailability();
535:         }
536:         mayNotifyAvailable(toNotify);
537:     }
538: 
539:     @GuardedBy("availableMemorySegments")
540:     private boolean shouldBeAvailable() {
541:         assert Thread.holdsLock(availableMemorySegments);
542: 
543:         return !availableMemorySegments.isEmpty() && unavailableSubpartitionsCount == 0;
544:     }
545: 
546:     @GuardedBy("availableMemorySegments")
547:     private CompletableFuture<?> checkAndUpdateAvailability() {
548:         assert Thread.holdsLock(availableMemorySegments);
549: 
550:         CompletableFuture<?> toNotify = null;
551: 
552:         AvailabilityStatus availabilityStatus = checkAvailability();
553:         if (availabilityStatus.isAvailable()) {
554:             toNotify = availabilityHelper.getUnavailableToResetAvailable();
555:         } else {
556:             availabilityHelper.resetUnavailable();
557:         }
558:         if (availabilityStatus.isNeedRequestingNotificationOfGlobalPoolAvailable()) {
559:             requestMemorySegmentFromGlobalWhenAvailable();
560:         }
561: 
562:         checkConsistentAvailability();
563:         return toNotify;
564:     }
565: 
566:     @GuardedBy("availableMemorySegments")
567:     private AvailabilityStatus checkAvailability() {
568:         assert Thread.holdsLock(availableMemorySegments);
569: 
570:         if (!availableMemorySegments.isEmpty()) {
571:             return AvailabilityStatus.from(shouldBeAvailable(), false);
572:         }
573:         if (isRequestedSizeReached()) {
574:             return AvailabilityStatus.UNAVAILABLE_NEED_NOT_REQUESTING_NOTIFICATION;
575:         }
576:         boolean needRequestingNotificationOfGlobalPoolAvailable = false;
577:         // There aren't availableMemorySegments, and we continue to request new memory segment from
578:         // global pool.
579:         if (!requestMemorySegmentFromGlobal()) {
580:             // If we can not get a buffer from global pool, we should request from it when it
581:             // becomes available. It should be noted that if we are already in this status, do not
582:             // need to repeat the request.
583:             needRequestingNotificationOfGlobalPoolAvailable =
584:                     !requestingNotificationOfGlobalPoolAvailable;
585:         }
586:         return AvailabilityStatus.from(
587:                 shouldBeAvailable(), needRequestingNotificationOfGlobalPoolAvailable);
588:     }
589: 
590:     @GuardedBy("availableMemorySegments")
591:     private void checkConsistentAvailability() {
592:         assert Thread.holdsLock(availableMemorySegments);
593: 
594:         final boolean shouldBeAvailable = shouldBeAvailable();
595:         checkState(
596:                 availabilityHelper.isApproximatelyAvailable() == shouldBeAvailable,
597:                 "Inconsistent availability: expected " + shouldBeAvailable);
598:     }
599: 
600:     @Override
601:     public void recycle(MemorySegment segment) {
602:         recycle(segment, UNKNOWN_CHANNEL);
603:     }
604: 
605:     private void recycle(MemorySegment segment, int channel) {
606:         BufferListener listener;
607:         CompletableFuture<?> toNotify = null;
608:         do {
609:             synchronized (availableMemorySegments) {
610:                 if (channel != UNKNOWN_CHANNEL) {
611:                     if (subpartitionBuffersCount[channel]-- == maxBuffersPerChannel) {
612:                         unavailableSubpartitionsCount--;
613:                     }
614:                 }
615: 
616:                 if (isDestroyed || hasExcessBuffers()) {
617:                     returnMemorySegment(segment);
618:                     return;
619:                 } else {
620:                     listener = registeredListeners.poll();
621:                     if (listener == null) {
622:                         availableMemorySegments.add(segment);
623:                         if (!availabilityHelper.isApproximatelyAvailable() && shouldBeAvailable()) {
624:                             toNotify = availabilityHelper.getUnavailableToResetAvailable();
625:                         }
626:                         break;
627:                     }
628:                 }
629: 
630:                 checkConsistentAvailability();
631:             }
632:         } while (!fireBufferAvailableNotification(listener, segment));
633: 
634:         mayNotifyAvailable(toNotify);
635:     }
636: 
637:     private boolean fireBufferAvailableNotification(
638:             BufferListener listener, MemorySegment segment) {
639:         // We do not know which locks have been acquired before the recycle() or are needed in the
640:         // notification and which other threads also access them.
641:         // -> call notifyBufferAvailable() outside the synchronized block to avoid a deadlock
642:         // (FLINK-9676)
643:         return listener.notifyBufferAvailable(new NetworkBuffer(segment, this));
644:     }
645: 
646:     /** Destroy is called after the produce or consume phase of a task finishes. */
647:     @Override
648:     public void lazyDestroy() {
649:         // NOTE: if you change this logic, be sure to update recycle() as well!
650:         CompletableFuture<?> toNotify = null;
651:         synchronized (availableMemorySegments) {
652:             if (!isDestroyed) {
653:                 MemorySegment segment;
654:                 while ((segment = availableMemorySegments.poll()) != null) {
655:                     returnMemorySegment(segment);
656:                 }
657: 
658:                 BufferListener listener;
659:                 while ((listener = registeredListeners.poll()) != null) {
660:                     listener.notifyBufferDestroyed();
661:                 }
662: 
663:                 if (!isAvailable()) {
664:                     toNotify = availabilityHelper.getAvailableFuture();
665:                 }
666: 
667:                 isDestroyed = true;
668:             }
669:         }
670: 
671:         mayNotifyAvailable(toNotify);
672: 
673:         networkBufferPool.destroyBufferPool(this);
674:     }
675: 
676:     @Override
677:     public boolean addBufferListener(BufferListener listener) {
678:         synchronized (availableMemorySegments) {
679:             if (!availableMemorySegments.isEmpty() || isDestroyed) {
680:                 return false;
681:             }
682: 
683:             registeredListeners.add(listener);
684:             return true;
685:         }
686:     }
687: 
688:     @Override
689:     public void setNumBuffers(int numBuffers) {
690:         CompletableFuture<?> toNotify;
691:         synchronized (availableMemorySegments) {
692:             checkArgument(
693:                     numBuffers >= minNumberOfMemorySegments,
694:                     "Buffer pool needs at least %s buffers, but tried to set to %s",
695:                     minNumberOfMemorySegments,
696:                     numBuffers);
697: 
698:             currentPoolSize = Math.min(numBuffers, maxNumberOfMemorySegments);
699: 
700:             returnExcessMemorySegments();
701: 
702:             if (isDestroyed) {
703:                 // FLINK-19964: when two local buffer pools are released concurrently, one of them
704:                 // gets buffers assigned
705:                 // make sure that checkAndUpdateAvailability is not called as it would proactively
706:                 // acquire one buffer from NetworkBufferPool.
707:                 return;
708:             }
709: 
710:             toNotify = checkAndUpdateAvailability();
711:         }
712: 
713:         mayNotifyAvailable(toNotify);
714:     }
715: 
716:     public void setMaxOverdraftBuffersPerGate(int maxOverdraftBuffersPerGate) {
717:         this.maxOverdraftBuffersPerGate = maxOverdraftBuffersPerGate;
718:     }
719: 
720:     public int getMaxOverdraftBuffersPerGate() {
721:         return maxOverdraftBuffersPerGate;
722:     }
723: 
724:     @Override
725:     public CompletableFuture<?> getAvailableFuture() {
726:         return availabilityHelper.getAvailableFuture();
727:     }
728: 
729:     @Override
730:     public String toString() {
731:         synchronized (availableMemorySegments) {
732:             return String.format(
733:                     this.hashCode()
734:                             + "[size: %d, requested: %d, available: %d, expected: %d, min: %d, max: %d, listeners: %d,"
735:                             + "subpartitions: %d, maxBuffersPerChannel: %d, destroyed: %s]",
736:                     currentPoolSize,
737:                     numberOfRequestedMemorySegments,
738:                     availableMemorySegments.size(),
739:                     expectedNumberOfMemorySegments,
740:                     minNumberOfMemorySegments,
741:                     maxNumberOfMemorySegments,
742:                     registeredListeners.size(),
743:                     subpartitionBuffersCount.length,
744:                     maxBuffersPerChannel,
745:                     isDestroyed);
746:         }
747:     }
