751:     /**
752:      * Notifies the potential segment consumer of the new available segments by completing the
753:      * previous uncompleted future.
754:      */
755:     private void mayNotifyAvailable(@Nullable CompletableFuture<?> toNotify) {
756:         if (toNotify != null) {
757:             toNotify.complete(null);
758:         }
759:     }
760: 
761:     @GuardedBy("availableMemorySegments")
762:     private void returnMemorySegment(MemorySegment segment) {
763:         assert Thread.holdsLock(availableMemorySegments);
764: 
765:         numberOfRequestedMemorySegments--;
766:         networkBufferPool.recyclePooledMemorySegment(segment);
767:     }
768: 
769:     @GuardedBy("availableMemorySegments")
770:     private void returnExcessMemorySegments() {
771:         assert Thread.holdsLock(availableMemorySegments);
772: 
773:         while (hasExcessBuffers()) {
774:             MemorySegment segment = availableMemorySegments.poll();
775:             if (segment == null) {
776:                 return;
777:             }
778: 
779:             returnMemorySegment(segment);
780:         }
781:     }
782: 
783:     @GuardedBy("availableMemorySegments")
784:     private boolean hasExcessBuffers() {
785:         return numberOfRequestedMemorySegments > currentPoolSize;
786:     }
787: 
788:     @GuardedBy("availableMemorySegments")
789:     private boolean isRequestedSizeReached() {
790:         return numberOfRequestedMemorySegments >= currentPoolSize;
791:     }
