793:     private static class SubpartitionBufferRecycler implements BufferRecycler {
794: 
795:         private final int channel;
796:         private final LocalBufferPool bufferPool;
797: 
798:         SubpartitionBufferRecycler(int channel, LocalBufferPool bufferPool) {
799:             this.channel = channel;
800:             this.bufferPool = bufferPool;
801:         }
802: 
803:         @Override
804:         public void recycle(MemorySegment memorySegment) {
805:             bufferPool.recycle(memorySegment, channel);
806:         }
807:     }
