809:     /**
810:      * This class represents the buffer pool's current ground-truth availability and whether to
811:      * request buffer from global pool when it is available.
812:      */
813:     private enum AvailabilityStatus {
814:         AVAILABLE(true, false),
815:         UNAVAILABLE_NEED_REQUESTING_NOTIFICATION(false, true),
816:         UNAVAILABLE_NEED_NOT_REQUESTING_NOTIFICATION(false, false);
817: 
818:         /** Indicates whether the {@link LocalBufferPool} is currently available. */
819:         private final boolean available;
820: 
821:         /**
822:          * Indicates whether to requesting notification of global pool when it becomes available.
823:          */
824:         private final boolean needRequestingNotificationOfGlobalPoolAvailable;
825: 
826:         AvailabilityStatus(
827:                 boolean available, boolean needRequestingNotificationOfGlobalPoolAvailable) {
828:             this.available = available;
829:             this.needRequestingNotificationOfGlobalPoolAvailable =
830:                     needRequestingNotificationOfGlobalPoolAvailable;
831:         }
832: 
833:         public boolean isAvailable() {
834:             return available;
835:         }
836: 
837:         public boolean isNeedRequestingNotificationOfGlobalPoolAvailable() {
838:             return needRequestingNotificationOfGlobalPoolAvailable;
839:         }
840: 
841:         public static AvailabilityStatus from(
842:                 boolean available, boolean needRequestingNotificationOfGlobalPoolAvailable) {
843:             if (available) {
844:                 checkState(
845:                         !needRequestingNotificationOfGlobalPoolAvailable,
846:                         "available local buffer pool should not request from global.");
847:                 return AVAILABLE;
848:             } else if (needRequestingNotificationOfGlobalPoolAvailable) {
849:                 return UNAVAILABLE_NEED_REQUESTING_NOTIFICATION;
850:             } else {
851:                 return UNAVAILABLE_NEED_NOT_REQUESTING_NOTIFICATION;
852:             }
853:         }
854:     }
855: }
